// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address actor, address newOwner) public {
        // initial owner is address(0); hand ownership to a fuzzed actor
        vm.assume(actor != address(0));
        vm.assume(newOwner != actor);

        // step 1: current owner (address(0)) transfers ownership to actor
        vm.prank(address(0));
        c.transferOwnership(actor);
        assertEq(c.owner(), actor);

        // step 2: actor (now owner) transfers ownership to newOwner
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: the current owner can always transfer ownership,
        // and afterwards owner == newOwner.
        assertTrue(ok && c.owner() == newOwner);
    }
}
